// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.text;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.assertj.core.api.Assertions.within;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.impl.BooleanLiteral;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.function.TupleFunction;
import org.eclipse.rdf4j.query.algebra.evaluation.function.json.JsonSupport;
import org.eclipse.rdf4j.query.algebra.evaluation.function.tuple.NgramsTupleFunction;
import org.eclipse.rdf4j.query.algebra.evaluation.function.tuple.TokenizeTupleFunction;
import org.junit.jupiter.api.Test;

/**
 * Edge cases of the {@code textf:} similarity, phonetic, pattern and tokenising functions.
 */
class TextFunctionsEdgeCaseTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private static final String SMILEY = "😀";

	private static final String GRIN = "😁";

	private static Literal str(String s) {
		return VF.createLiteral(s);
	}

	private static Literal integer(int i) {
		return VF.createLiteral(i);
	}

	private static double dbl(Literal literal) {
		assertThat(literal.getDatatype()).isEqualTo(XSD.DOUBLE);
		return literal.doubleValue();
	}

	private static List<Value> jsonArrayValues(Literal array) {
		assertThat(array.getCoreDatatype()).isEqualTo(CoreDatatype.RDF.JSON);
		List<?> parsed = (List<?>) JsonSupport.parse(array.getLabel());
		List<Value> values = new ArrayList<>(parsed.size());
		for (Object element : parsed) {
			values.add(JsonSupport.toValue(element, VF));
		}
		return values;
	}

	private static List<Value> rows(TupleFunction function, Value... args) {
		List<Value> values = new ArrayList<>();
		try (var rows = function.evaluate(VF, args)) {
			while (rows.hasNext()) {
				List<? extends Value> row = rows.next();
				assertThat(row).hasSize(1);
				values.add(row.get(0));
			}
		}
		return values;
	}

	// ---------------------------------------------------------------- levenshtein, damerauLevenshtein

	@Test
	void editDistanceOfIdenticalAndEmptyStrings() {
		assertThat(new Levenshtein().evaluate(VF, str("abc"), str("abc")).intValue()).isEqualTo(0);
		assertThat(new DamerauLevenshtein().evaluate(VF, str("abc"), str("abc")).intValue()).isEqualTo(0);
		assertThat(new Levenshtein().evaluate(VF, str("abc"), str("")).intValue()).isEqualTo(3);
		assertThat(new DamerauLevenshtein().evaluate(VF, str(""), str("abcd")).intValue()).isEqualTo(4);
		assertThat(new DamerauLevenshtein().evaluate(VF, str("abcd"), str("")).intValue()).isEqualTo(4);
		assertThat(new Levenshtein().evaluate(VF, str(""), str("")).intValue()).isEqualTo(0);
		assertThat(new DamerauLevenshtein().evaluate(VF, str(""), str("")).intValue()).isEqualTo(0);
	}

	@Test
	void editDistanceIsCaseSensitiveAndCountsAstralCodePointsOnce() {
		assertThat(new Levenshtein().evaluate(VF, str("Abc"), str("abc")).intValue()).isEqualTo(1);
		assertThat(new DamerauLevenshtein().evaluate(VF, str("ABC"), str("abc")).intValue()).isEqualTo(3);
		assertThat(new DamerauLevenshtein().evaluate(VF, str(SMILEY + "a"), str("a")).intValue()).isEqualTo(1);
		assertThat(new Levenshtein().evaluate(VF, str(SMILEY), str(GRIN)).intValue()).isEqualTo(1);
		assertThat(new DamerauLevenshtein().evaluate(VF, str(SMILEY + GRIN), str(GRIN + SMILEY)).intValue())
				.isEqualTo(1);
		assertThat(new Levenshtein().evaluate(VF, str(SMILEY + GRIN), str(GRIN + SMILEY)).intValue()).isEqualTo(2);
	}

	@Test
	void levenshteinOfTenThousandCharacterStringsCompletes() {
		Literal a = str("a".repeat(10_000));
		Literal b = str("b".repeat(10_000));
		Literal shifted = str("x" + "a".repeat(9_999));
		Literal distance = new Levenshtein().evaluate(VF, a, b);
		assertThat(distance.getDatatype()).isEqualTo(XSD.INTEGER);
		assertThat(distance.intValue()).isEqualTo(10_000);
		assertThat(new Levenshtein().evaluate(VF, a, shifted).intValue()).isEqualTo(1);
		assertThat(new Levenshtein().evaluate(VF, a, str("a".repeat(5_000))).intValue()).isEqualTo(5_000);
	}

	@Test
	void damerauLevenshteinOfTenThousandCharacterStringsIsRejectedByTheSizeGuard() {
		// pins current behaviour: the unrestricted distance needs an (n+2)(m+2) matrix, so inputs above the guard
		// (about 2000 x 2000 code points) are an evaluation error instead of a 400 MB allocation
		Literal a = str("a".repeat(10_000));
		Literal b = str("b".repeat(10_000));
		assertThatThrownBy(() -> new DamerauLevenshtein().evaluate(VF, a, b))
				.isInstanceOf(ValueExprEvaluationException.class)
				.hasMessageContaining("too long");
		assertThat(new DamerauLevenshtein().evaluate(VF, str("a".repeat(2_000)), str("b".repeat(2_000))).intValue())
				.isEqualTo(2_000);
		// a short string against a long one stays within the guard
		assertThat(new DamerauLevenshtein().evaluate(VF, str("ab"), a).intValue()).isEqualTo(9_999);
	}

	// ---------------------------------------------------------------- jaroSimilarity, jaroWinkler

	@Test
	void jaroBoundaryValues() {
		assertThat(dbl(new JaroSimilarity().evaluate(VF, str("abc"), str("abc")))).isEqualTo(1.0);
		assertThat(dbl(new JaroWinkler().evaluate(VF, str("abc"), str("abc")))).isEqualTo(1.0);
		assertThat(dbl(new JaroWinkler().evaluate(VF, str("abc"), str("xyz")))).isEqualTo(0.0);
		// pins current behaviour: two empty strings are identical (1.0), one empty string has no similarity (0.0)
		assertThat(dbl(new JaroWinkler().evaluate(VF, str(""), str("")))).isEqualTo(1.0);
		assertThat(dbl(new JaroSimilarity().evaluate(VF, str(""), str("abc")))).isEqualTo(0.0);
		assertThat(dbl(new JaroWinkler().evaluate(VF, str("abc"), str("")))).isEqualTo(0.0);
		assertThat(dbl(new JaroSimilarity().evaluate(VF, str(SMILEY + "a"), str(SMILEY + "a")))).isEqualTo(1.0);
	}

	@Test
	void jaroWinklerPrefixBoostIsCappedAtFourCharacters() {
		Literal a = str("abcdefgh");
		Literal b = str("abcdexyz"); // common prefix of five
		double jaro = dbl(new JaroSimilarity().evaluate(VF, a, b));
		assertThat(jaro).isStrictlyBetween(0.0, 1.0);
		assertThat(dbl(new JaroWinkler().evaluate(VF, a, b))).isCloseTo(jaro + 4 * 0.1 * (1 - jaro), within(1e-12));

		Literal c = str("abxyz");
		Literal d = str("abqrs"); // common prefix of two
		double jaroCd = dbl(new JaroSimilarity().evaluate(VF, c, d));
		assertThat(dbl(new JaroWinkler().evaluate(VF, c, d))).isCloseTo(jaroCd + 2 * 0.1 * (1 - jaroCd),
				within(1e-12));
	}

	@Test
	void jaroWinklerScalingDefaultAndBounds() {
		Literal a = str("abcdefgh");
		Literal b = str("abcdexyz");
		double jaro = dbl(new JaroSimilarity().evaluate(VF, a, b));
		assertThat(new JaroWinkler().evaluate(VF, a, b))
				.isEqualTo(new JaroWinkler().evaluate(VF, a, b, VF.createLiteral(0.1)));
		assertThat(dbl(new JaroWinkler().evaluate(VF, a, b, VF.createLiteral(0.25))))
				.isCloseTo(jaro + 4 * 0.25 * (1 - jaro), within(1e-12));
		assertThat(dbl(new JaroWinkler().evaluate(VF, a, b, integer(0)))).isEqualTo(jaro);
		// pins current behaviour: the standard cap of 0.25 is enforced
		assertThatThrownBy(() -> new JaroWinkler().evaluate(VF, a, b, VF.createLiteral(0.26)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JaroWinkler().evaluate(VF, a, b, VF.createLiteral(-0.1)))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void jaroWinklerScalingMustBeABoundNumericLiteral() {
		Literal a = str("abc");
		Literal b = str("abd");
		assertThatThrownBy(() -> new JaroWinkler().evaluate(VF, a, b, null))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JaroWinkler().evaluate(VF, a, b, str("0.1")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JaroWinkler().evaluate(VF, a, b, VF.createLiteral("x", XSD.DOUBLE)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JaroWinkler().evaluate(VF, a, b, VF.createIRI("urn:x")))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	// ---------------------------------------------------------------- soundex, metaphone

	@Test
	void soundexStripsNonLettersAndHandlesEmptyInput() {
		assertThat(new Soundex().evaluate(VF, str("R-o.b 3ert!"))).isEqualTo(str("R163"));
		assertThat(new Soundex().evaluate(VF, str("ROBERT"))).isEqualTo(str("R163"));
		// pins current behaviour: no letters at all gives "" rather than an error
		assertThat(new Soundex().evaluate(VF, str(""))).isEqualTo(str(""));
		assertThat(new Soundex().evaluate(VF, str(" -42 "))).isEqualTo(str(""));
		assertThat(new Soundex().evaluate(VF, str("A"))).isEqualTo(str("A000"));
		assertThat(new Soundex().evaluate(VF, str("Lee"))).isEqualTo(str("L000"));
	}

	@Test
	void soundexAndMetaphoneSkipNonAsciiLetters() {
		// pins current behaviour: only ASCII letters are coded; "Ärger" is coded as "rger"
		assertThat(new Soundex().evaluate(VF, str("Ärger"))).isEqualTo(str("R260"));
		assertThat(new Soundex().evaluate(VF, str("Ärger"))).isEqualTo(new Soundex().evaluate(VF, str("rger")));
		assertThat(new Metaphone().evaluate(VF, str("Ärger"))).isEqualTo(new Metaphone().evaluate(VF, str("rger")));
		assertThat(new Metaphone().evaluate(VF, str("Ärger"))).isEqualTo(str("RJR"));
		assertThat(new Soundex().evaluate(VF, str("ÄÖÜ"))).isEqualTo(str(""));
		assertThat(new Metaphone().evaluate(VF, str(SMILEY))).isEqualTo(str(""));
	}

	@Test
	void metaphoneMaxLength() {
		assertThatThrownBy(() -> new Metaphone().evaluate(VF, str("Thompson"), integer(0)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new Metaphone().evaluate(VF, str("Thompson"), integer(-4)))
				.isInstanceOf(ValueExprEvaluationException.class);
		// the default is 4
		Literal thompson = new Metaphone().evaluate(VF, str("Thompson"));
		assertThat(thompson).isEqualTo(new Metaphone().evaluate(VF, str("Thompson"), integer(4)));
		assertThat(thompson.getLabel()).hasSize(4);
		// pins current behaviour: the original Metaphone codes "TH" as '0' (theta), so "Thompson" is "0MPS"
		assertThat(thompson).isEqualTo(str("0MPS"));
		assertThat(new Metaphone().evaluate(VF, str("Thompson"), integer(1))).isEqualTo(str("0"));
		assertThat(new Metaphone().evaluate(VF, str("Thompson"), integer(10))).isEqualTo(str("0MPSN"));
		assertThat(new Metaphone().evaluate(VF, str("Schwarzenegger"), integer(4)).getLabel()).hasSize(4);
		assertThat(new Metaphone().evaluate(VF, str("Schwarzenegger"), integer(100)).getLabel().length())
				.isGreaterThan(4);
	}

	// ---------------------------------------------------------------- trigramSimilarity

	@Test
	void trigramSimilarityReproducesPgTrgmValues() {
		// pg_trgm: similarity('cat', 'cats') = 0.5
		assertThat(dbl(new TrigramSimilarity().evaluate(VF, str("cat"), str("cats")))).isEqualTo(0.5);
		assertThat(TrigramSimilarity.trigrams("word")).containsExactlyInAnyOrder("  w", " wo", "wor", "ord", "rd ");
		assertThat(TrigramSimilarity.trigrams("two words")).hasSize(10); // 4 + 10 - 4 shared = 11 -> 4/11
	}

	@Test
	void trigramSimilarityBoundaries() {
		assertThat(dbl(new TrigramSimilarity().evaluate(VF, str("Hello World"), str("Hello World")))).isEqualTo(1.0);
		assertThat(dbl(new TrigramSimilarity().evaluate(VF, str(""), str("abc")))).isEqualTo(0.0);
		assertThat(dbl(new TrigramSimilarity().evaluate(VF, str("abc"), str("")))).isEqualTo(0.0);
		assertThat(dbl(new TrigramSimilarity().evaluate(VF, str("abc"), str("xyz")))).isEqualTo(0.0);
	}

	@Test
	void trigramSimilarityIgnoresCaseAndNonAlphanumerics() {
		assertThat(dbl(new TrigramSimilarity().evaluate(VF, str("HELLO world"), str("hello WORLD")))).isEqualTo(1.0);
		assertThat(dbl(new TrigramSimilarity().evaluate(VF, str("a-b"), str("a b")))).isEqualTo(1.0);
		assertThat(dbl(new TrigramSimilarity().evaluate(VF, str("word!"), str("word")))).isEqualTo(1.0);
		assertThat(dbl(new TrigramSimilarity().evaluate(VF, str("***"), str("---")))).isEqualTo(0.0);
		assertThat(TrigramSimilarity.trigrams("É")).isEqualTo(TrigramSimilarity.trigrams("é"));
	}

	// ---------------------------------------------------------------- ilike

	@Test
	void ilikeEscapeHandling() {
		assertThat(new ILike().evaluate(VF, str("50% off"), str("50\\% off"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("a_c"), str("a\\_c"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("abc"), str("a\\_c"))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(new ILike().evaluate(VF, str("a\\b"), str("a\\\\b"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("a%b"), str("a#%b"), str("#"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("a\\b"), str("a\\b"), str("#"))).isEqualTo(BooleanLiteral.TRUE);
		assertThatThrownBy(() -> new ILike().evaluate(VF, str("abc"), str("a%"), str("!!")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new ILike().evaluate(VF, str("abc"), str("a%"), str("")))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void ilikeEscapeCharacterAtEndOfPatternIsAnEvaluationError() {
		assertThatThrownBy(() -> new ILike().evaluate(VF, str("a"), str("a\\")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new ILike().evaluate(VF, str("a\\"), str("a\\")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new ILike().evaluate(VF, str("a"), str("a#"), str("#")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new ILike().evaluate(VF, str(""), str("\\")))
				.isInstanceOf(ValueExprEvaluationException.class);
		// an escaped escape character at the end is fine
		assertThat(new ILike().evaluate(VF, str("a\\"), str("a\\\\"))).isEqualTo(BooleanLiteral.TRUE);
	}

	@Test
	void ilikeIsCaseInsensitiveBeyondAscii() {
		assertThat(new ILike().evaluate(VF, str("É"), str("é"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("ÉCOLE"), str("école"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("Straße"), str("STRAßE"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("ΣΟΦΊΑ"), str("σοφία"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("É"), str("e"))).isEqualTo(BooleanLiteral.FALSE);
	}

	@Test
	void ilikeTreatsRegexMetacharactersLiterally() {
		assertThat(new ILike().evaluate(VF, str("aXb"), str("a.b"))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(new ILike().evaluate(VF, str("a.b"), str("a.b"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("ab"), str("a*b"))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(new ILike().evaluate(VF, str("a*b"), str("a*b"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("abc"), str("[abc]"))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(new ILike().evaluate(VF, str("(a|b)"), str("(a|b)"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("a"), str("(a|b)"))).isEqualTo(BooleanLiteral.FALSE);
	}

	@Test
	void ilikeEmptyPatternMatchesOnlyTheEmptyString() {
		assertThat(new ILike().evaluate(VF, str(""), str(""))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("a"), str(""))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(new ILike().evaluate(VF, str(""), str("%%"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str(""), str("%_"))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(new ILike().evaluate(VF, str("abc"), str("%"))).isEqualTo(BooleanLiteral.TRUE);
	}

	@Test
	void ilikeUnderscoreMatchesOneAstralCodePoint() {
		assertThat(new ILike().evaluate(VF, str(SMILEY), str("_"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str(SMILEY), str("__"))).isEqualTo(BooleanLiteral.FALSE);
		assertThat(new ILike().evaluate(VF, str("a" + SMILEY + "b"), str("a_b"))).isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("a" + SMILEY + "b"), str("a" + SMILEY + "%")))
				.isEqualTo(BooleanLiteral.TRUE);
		assertThat(new ILike().evaluate(VF, str("a" + SMILEY + "b"), str("a" + GRIN + "%")))
				.isEqualTo(BooleanLiteral.FALSE);
	}

	// ---------------------------------------------------------------- tokenize, ngrams

	@Test
	void tokenizeEmptyAndWhitespaceOnlyInput() {
		assertThat(new Tokenize().evaluate(VF, str("")).getLabel()).isEqualTo("[]");
		assertThat(new Tokenize().evaluate(VF, str(" \t\n  ")).getLabel()).isEqualTo("[]");
		assertThat(new Tokenize().evaluate(VF, str("...!?")).getLabel()).isEqualTo("[]");
	}

	@Test
	void tokenizePunctuationHandling() {
		// pins current behaviour: apostrophes and connector punctuation stay inside tokens, everything else splits
		assertThat(new Tokenize().evaluate(VF, str("a, b; c.")).getLabel()).isEqualTo("[\"a\",\"b\",\"c\"]");
		assertThat(new Tokenize().evaluate(VF, str("don't stop-me")).getLabel())
				.isEqualTo("[\"don't\",\"stop\",\"me\"]");
		assertThat(new Tokenize().evaluate(VF, str("snake_case 'quoted'")).getLabel())
				.isEqualTo("[\"snake_case\",\"'quoted'\"]");
		assertThat(new Tokenize().evaluate(VF, str("e-mail@example.com")).getLabel())
				.isEqualTo("[\"e\",\"mail\",\"example\",\"com\"]");
	}

	@Test
	void tokenizeUnicodeWordBoundaries() {
		// pins current behaviour: letters of every script are token characters, so CJK text is split on spaces and
		// punctuation only, not into words
		assertThat(new Tokenize().evaluate(VF, str("日本語 テキスト")).getLabel())
				.isEqualTo("[\"日本語\",\"テキスト\"]");
		assertThat(new Tokenize().evaluate(VF, str("中文,English")).getLabel()).isEqualTo("[\"中文\",\"English\"]");
		assertThat(new Tokenize().evaluate(VF, str("héllo wörld")).getLabel()).isEqualTo("[\"héllo\",\"wörld\"]");
		assertThat(new Tokenize().evaluate(VF, str("a" + SMILEY + "b")).getLabel()).isEqualTo("[\"a\",\"b\"]");
	}

	@Test
	void ngramsLengthEdgeCases() {
		assertThat(new Ngrams().evaluate(VF, str("abc"), integer(1)).getLabel()).isEqualTo("[\"a\",\"b\",\"c\"]");
		assertThat(new Ngrams().evaluate(VF, str("abc"), integer(3)).getLabel()).isEqualTo("[\"abc\"]");
		assertThat(new Ngrams().evaluate(VF, str("abc"), integer(4)).getLabel()).isEqualTo("[]");
		assertThat(new Ngrams().evaluate(VF, str(""), integer(1)).getLabel()).isEqualTo("[]");
		assertThat(new Ngrams().evaluate(VF, str(SMILEY + GRIN + "x"), integer(1)).getLabel())
				.isEqualTo("[\"" + SMILEY + "\",\"" + GRIN + "\",\"x\"]");
		assertThatThrownBy(() -> new Ngrams().evaluate(VF, str("abc"), integer(-1)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new Ngrams().evaluate(VF, str("abc"), integer(Integer.MIN_VALUE)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThat(new Ngrams().evaluate(VF, str("abc"), integer(Integer.MAX_VALUE)).getLabel()).isEqualTo("[]");
	}

	@Test
	void tokenizeMagicPropertyYieldsTheSameTokensInOrder() {
		TokenizeTupleFunction tupleFunction = new TokenizeTupleFunction();
		Tokenize scalar = new Tokenize();
		for (Literal input : List.of(str("Hello, world! It's rdf4j_core v2."), str(""), str("   "),
				str("日本語 テキスト"), str("a" + SMILEY + "b"), VF.createLiteral("x y", "en"))) {
			List<Value> array = jsonArrayValues(scalar.evaluate(VF, input));
			List<Value> tuples = rows(tupleFunction, input);
			assertThat(tuples).as(input.toString()).containsExactlyElementsOf(array);
		}
	}

	@Test
	void ngramsMagicPropertyYieldsTheSameGramsInOrder() {
		NgramsTupleFunction tupleFunction = new NgramsTupleFunction();
		Ngrams scalar = new Ngrams();
		for (Literal input : List.of(str("abcd"), str("ab"), str(""), str("a" + SMILEY + "b" + GRIN),
				VF.createLiteral("xyz", "en"))) {
			for (int n : new int[] { 1, 2, 3, 5 }) {
				List<Value> array = jsonArrayValues(scalar.evaluate(VF, input, integer(n)));
				List<Value> tuples = rows(tupleFunction, input, integer(n));
				assertThat(tuples).as(input + " n=" + n).containsExactlyElementsOf(array);
			}
		}
	}
}
